add_action( 'woocommerce_email_before_order_table', 'perfectpixel_email_item_meta_on', 1 );
add_action( 'woocommerce_email_after_order_table', 'perfectpixel_email_item_meta_off', 99 );

function perfectpixel_email_item_meta_on() {
	add_filter( 'woocommerce_display_item_meta', 'perfectpixel_tidy_email_item_meta', 10, 2 );
}

function perfectpixel_email_item_meta_off() {
	remove_filter( 'woocommerce_display_item_meta', 'perfectpixel_tidy_email_item_meta', 10 );
}

function perfectpixel_tidy_email_item_meta( $html, $item ) {
	$lines = array();
	foreach ( $item->get_all_formatted_meta_data() as $meta ) {
		$lines[] = '<span style="display:block">' . wp_kses_post( $meta->display_key ) . ': ' . wp_kses_post( wp_strip_all_tags( $meta->display_value ) ) . '</span>';
	}
	return $lines ? '<div class="perfectpixel-item-meta" style="margin-top:4px;font-size:12px;line-height:1.5;color:#646970">' . implode( '', $lines ) . '</div>' : '';
}
